<?php require __DIR__.'/../includes/bootstrap.php'; admin_required();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='hours'){db()->exec('DELETE FROM business_hours');for($w=0;$w<=6;$w++){if(isset($_POST['active'][$w])){foreach($_POST['start'][$w]??[] as $i=>$start){$end=$_POST['end'][$w][$i]??'';if($start&&$end&&$start<$end)db()->prepare('INSERT INTO business_hours(weekday,start_time,end_time) VALUES (?,?,?)')->execute([$w,$start,$end]);}}}flash('ok','Horários atualizados.');}if($action==='block'){db()->prepare('INSERT INTO schedule_blocks(block_date,start_time,end_time,reason) VALUES (?,?,?,?)')->execute([$_POST['block_date'],$_POST['start_time'],$_POST['end_time'],trim($_POST['reason'])?:null]);flash('ok','Bloqueio criado.');}if($action==='delete_block'){db()->prepare('DELETE FROM schedule_blocks WHERE id=?')->execute([(int)$_POST['id']]);}header('Location: schedule.php');exit;}
$hours=db()->query('SELECT * FROM business_hours ORDER BY weekday,start_time')->fetchAll();$by=[];foreach($hours as $h)$by[$h['weekday']][]=$h;$blocks=db()->query('SELECT * FROM schedule_blocks WHERE block_date>=CURDATE() ORDER BY block_date,start_time LIMIT 100')->fetchAll();$names=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];$msg=flash('ok');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Horários | PG Estética</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-shell"><?php include '_nav.php'; ?><section><div class="container"><span class="eyebrow">disponibilidade</span><h1>Horários da clínica</h1><?php if($msg): ?><div class="notice"><?= e($msg) ?></div><?php endif; ?><div class="two-col"><div class="panel"><h2>Jornada semanal</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="hours"><?php foreach($names as $w=>$name): $r=$by[$w][0]??null; ?><div class="hours-row"><label><input type="checkbox" name="active[<?= $w ?>]" <?= $r?'checked':'' ?>> <?= $name ?></label><input type="time" name="start[<?= $w ?>][]" value="<?= $r?substr($r['start_time'],0,5):'09:00' ?>"><span>até</span><input type="time" name="end[<?= $w ?>][]" value="<?= $r?substr($r['end_time'],0,5):'18:00' ?>"></div><?php endforeach; ?><button class="btn btn-primary" type="submit">Salvar jornada</button></form></div><div class="panel"><h2>Bloquear horário</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="block"><label>Data</label><input type="date" name="block_date" min="<?= date('Y-m-d') ?>" required><div class="row"><div><label>Início</label><input type="time" name="start_time" required></div><div><label>Fim</label><input type="time" name="end_time" required></div></div><label>Motivo</label><input name="reason" placeholder="Almoço, reunião, feriado..."><button class="btn btn-primary" type="submit">Criar bloqueio</button></form><h3>Próximos bloqueios</h3><?php foreach($blocks as $b): ?><div class="block-row"><span><?= date('d/m/Y',strtotime($b['block_date'])) ?> · <?= substr($b['start_time'],0,5) ?>–<?= substr($b['end_time'],0,5) ?> · <?= e($b['reason']) ?></span><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_block"><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><button class="link-danger">remover</button></form></div><?php endforeach; ?></div></div></div></section></body></html>
